"""Legacy-compatible validation for OPP_MASTER opportunities."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _value(record: dict, field: str) -> Any:
    value = record.get(field, "")
    return "" if value is None else value


def _number(value: Any) -> Decimal:
    """Apply VRL numeric coercion; empty or missing values become zero."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        # The required interface permits only numbers, numeric strings, or empty
        # values for NUMBER columns, so this path is outside its input contract.
        return Decimal(0)


def _date_gte(left: Any, right: Any) -> bool:
    """Apply VRL ordering semantics for YYYYMMDD date strings."""
    left_text = "" if left is None else str(left)
    right_text = "" if right is None else str(right)

    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def _failure(
    code: str,
    message: str,
    severity: str = "BLOCK",
) -> dict:
    return {
        "code": code,
        "message": message,
        "severity": severity,
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate all applicable opportunity rules in legacy rule-file order."""
    errors: list[dict] = []

    stat_cd = _value(record, "STAT_CD")
    amount = _number(_value(record, "AMT"))
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _number(_value(record, "STAGE_PCT"))

    if event in ("INSERT", "UPDATE"):
        # OPP-001
        if not (amount >= 0):
            errors.append(_failure("E3001", "Amount negative"))

        # OPP-002
        if not (not (stat_cd == "W" and amount == 0)):
            errors.append(
                _failure("E3002", "Won opportunity requires amount")
            )

        # OPP-003
        if not (not (stat_cd == "L" and lost_rsn == "")):
            errors.append(_failure("E3003", "Lost reason required"))

        # OPP-004
        if not (not (stat_cd == "W" and close_dt == "00000000")):
            errors.append(
                _failure("E3004", "Won opportunity requires close date")
            )

    if event == "UPDATE":
        # OPP-005
        old_record = old or {}
        old_stat_cd = _value(old_record, "STAT_CD")
        if not (not (old_stat_cd == "W" and stat_cd != "W")):
            errors.append(
                _failure("E3005", "Cannot reopen a won opportunity")
            )

    if event in ("INSERT", "UPDATE"):
        # OPP-006
        stage_is_consistent = (
            (stat_cd == "P" and stage_pct == 10)
            or (stat_cd == "Q" and stage_pct == 25)
            or (stat_cd == "N" and stage_pct == 60)
            or (stat_cd == "W" and stage_pct == 100)
            or (stat_cd == "L" and stage_pct == 0)
        )
        if not stage_is_consistent:
            errors.append(
                _failure(
                    "E3006",
                    "Stage percent inconsistent with status",
                )
            )

    if event == "INSERT":
        # OPP-007
        close_date_is_valid = (
            close_dt == "00000000" or _date_gte(close_dt, today)
        )
        if not close_date_is_valid:
            errors.append(
                _failure(
                    "E3007",
                    "Close date in past",
                    severity="WARN",
                )
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return True when at least one collected validation failure blocks."""
    return any(error.get("severity") == "BLOCK" for error in errors)
